{
  "findings": [
    {
      "check_id": "CKV_AWS_88",
      "title": "Launch configuration allows public IP assignment",
      "resource": "aws_launch_configuration.lc",
      "severity": "HIGH",
      "explanation": "The `associate_public_ip_address` is set to `true`, which assigns a public IP to instances launched with this configuration. This can expose the instances to the public internet, increasing the attack surface."
    }
  ],
  "patched_code": "resource "aws_launch_configuration" "lc" {
  name          = "test_ecs"
  image_id      = data.aws_ami.amazon_linux.id
  instance_type = "t2.micro"
  lifecycle {
    create_before_destroy = true
  }
  iam_instance_profile        = aws_iam_instance_profile.ecs_service_role.name
  key_name                    = var.key_name
  security_groups             = [aws_security_group.ec2-sg.id]
  associate_public_ip_address = false
  user_data                   = <<EOF
sudo apt-get update
sudo echo "ECS_CLUSTER=${var.cluster_name}" >> /etc/ecs/ecs.config
EOF
}",
  "fix_summary": "Set `associate_public_ip_address` to `false` to prevent instances from being assigned public IPs, reducing exposure to the public internet."
}
